-- GENERATED by `wfj generate` from data/gossip/gossip-3a.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3a001ad43967f98e"] = { "Consegno l'uomo al mio signore perché venga punito, poiché ha infranto la legge del regno ed è mio dovere giurato farla rispettare.", "." },
  ["3a007267a5a3588d"] = { "Pelli? Sì, ho appena ricevuto notizie in merito. Pare che, dei $2067w di cuoio pesante necessari, l'⟦Horde=Orda⟧ ne abbia raccolti $2066w. Inoltre sono stati raccolti $2070w di cuoio spesso su $2071w e $2073w di cuoio duro su $2074w.", "." },
  ["3a0eeeb302f3dc03"] = { "Non posso insegnarti la conciatura elementale, {name}. Devi andare a Tanaris e trovare la casa di ⟦Narain Soothfancy=Narain Veravite⟧. Una volta lì, consulta il libro \"Soothsaying for Dummies\".", "." },
  ["3a0f5540d793983f"] = { "L'anziano Stonefort si è rifugiato nelle segrete dei ⟦Blackrock Spire=Bastioni di Roccianera⟧.", "." },
  ["3a1bba19686a460c"] = { "I Creatori sono consapevoli della portata delle informazioni custodite in questo archivio. Di conseguenza, una copia portatile dei dati qui conservati ti sarà resa disponibile una volta che sarai in sintonia con i Discs of Norgannon.\n\nConsidera completi i requisiti preliminari per l'assimilazione di questa conoscenza. Quando vorrai, accedi ai Discs of Norgannon per iniziare la sintesi dei tuoi dischi.", "." },
  ["3a249af523cac25a"] = { "Solo carne e ossa. I mortali sono prede così facili...", "." },
  ["3a27409188a3ab7a"] = { "Non tutti i Reietti sono mossi dalla volontà di Sylvanas, {name}. Alcuni di noi sono mossi dal vero potere... un potere che ci guadagniamo da soli.", "." },
  ["3a282524d04a2556"] = { "Ecco fatto: ora puoi fabbricare un First Aid Kit tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", "." },
  ["3a37108a208c5235"] = { "Osi profanare questo suolo sacro?", "." },
  ["3a3ba39e09b464fc"] = { "Un ⟦Ash'ari Crystal=Cristallo Ash'ari⟧ è caduto! Restate fedeli al Re dei Lich, fratelli miei, e cercate di evocarlo di nuovo.", "." },
  ["3a3beeaff3d5a48a"] = { "Grazie per il tuo impegno, {name}. Ultimamente c'è stata un'ondata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e al resto penseremo noi.\n\nEcco il tuo compenso.", "." },
  ["3a3fd5a4dbf30352"] = { "Quanto al tuo avvertimento, non preoccuparti. Le nostre truppe conoscono bene la catena di comando. Combattiamo uniti. Speriamo che anche le tue truppe se ne ricordino...", "." },
  ["3a46a0649b834fad"] = { "Il ⟦Darrowshire=Borgo di Darrow⟧ è sconfitto! Presto tutta Lordaeron cadrà!", "." },
  ["3a4d24708694274c"] = { "Salve, {class}. Confido che tu porti buone notizie sui preparativi per la guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Mi è stata affidata la raccolta di tutto il cuoio duro per l'⟦Horde=Orda⟧, un compito per cui ho un talento particolare. Mai sottovalutare l'utilità di un coltello ben affilato.\n\nQuanto al cuoio duro, al momento ne abbiamo $2073w sui $2074w necessari.", "." },
  ["3a58b3410c36b1d6"] = { "Come faccio a combinare qualcosa con il Flagello che imperversa qui intorno?!", "." },
  ["3a5c35146474cd68"] = { "Credo di sentirlo arrivare! Guardate a ovest!", "." },
  ["3a6077ad29cd845f"] = { "La resistenza di Woo Ping è semplicemente incredibile. Dopo averlo visto esercitarsi per ore con le sue tecniche d'arma, provavo pena per il manichino. Non mi viene in mente nessuno più adatto ad addestrarti nel combattimento armato.", "." },
  ["3a6b119242748e4d"] = { "Eccomi! Ora, miseri vermiciattoli, pagherete per la vostra intrusione!", "." },
  ["3a6ca1bf81cf18ec"] = { "La battaglia per la ⟦Alterac Valley=Valle d'Alterac⟧ è cominciata!", "." },
  ["3a7e847ff4f2e004"] = { "Tu, soldato, torna subito a fare rapporto a Kargath!", "." },
  ["3a88434a6a6a3751"] = { "Darò in pasto le vostre anime a Hakkar in persona!", "." },
  ["3a89125f5f1c0876"] = { "Davanti a te c'è un congegno dall'aria bizzarra, con una semplice targa che ne annuncia il nome: \"La Lavatutto 5200\". La macchina sembra progettata per far tornare gli oggetti lucidi e nuovi.", "." },
  ["3a9369416d404b7f"] = { "Allora devi parlare con ⟦Taim Ragetotem=Taim Totem Rabbioso⟧. Cercalo sull'⟦Hunter Rise=Altura dei Cacciatori⟧.", "." },
  ["3aa545600b0feaca"] = { "Come Kel'Thuzad, anch'io un tempo ero un mago del Kirin Tor. E come Kel'Thuzad, cerco il leggendario Atiesh, Granbastone del Guardiano. I nostri destini sono quindi intrecciati, {class}.", "." },
  ["3aa69d6d26ed4bce"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare gli ⟦Wild Leather Boots=Stivali di Cuoio Selvatico⟧?", "." },
  ["3aa70cdd399cedcc"] = { "Forse... E adesso che faccio?", "." },
  ["3aaec33683c6cb5b"] = { "Non abbiamo nascosto questa roba perché tu potessi rubarla!", "." },
  ["3ab2446bdc018f8c"] = { "Ah. <Benvenuto/Benvenuta>, <signore/signora>!", "." },
  ["3ab36feab4a43c30"] = { "Noi dell'⟦Horde=Orda⟧ abbiamo fatto tutto il possibile per prepararci alla guerra imminente ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Ora aspettiamo, {class}, che l'⟦Alliance=Alleanza⟧ faccia lo stesso. Quando avranno finito, trasporteremo tutti il nostro materiale bellico alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧.", "." },
  ["3ab5c17029596ca4"] = { "Eranikus, Tiranno del Sogno, è interamente consumato dalla ⟦Light of Elune=Luce di Elune⟧. La quiete scende su ⟦Moonglade=Radaluna⟧.", "." },
  ["3ab66a4be66918b5"] = { "Sono assolutamente sicur<o/a> di voler imparare la conciatura di scaglie di drago.", "." },
  ["3ab81aed9e3f5b2f"] = { "Ai vostri posti! Nessun invasore deve raggiungere ⟦Southshore=Riva del Sud⟧!", "." },
  ["3abac24dd211e159"] = { "Non c'è cuoca migliore a ⟦Thunder Bluff=Picco del Tuono⟧ di ⟦Aska Mistrunner=Aska Cavalca Nebbia⟧. Mmmmm, sento da qui il profumo di quello che cucina. Raggiungi la sua cucina sull'altura più alta.\n\nAccidenti... ora mi è venuta fame.", "." },
  ["3ac09870bb560d4a"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quegli alberiani corrotti con il potere di Elune al mio fianco!", "." },
  ["3ac415bc16acaab9"] = { "Ecco un esempio di ciò che non bisogna evocare. Guardate, è fragile e friabile. Un bel colpo di mazza e le schegge d'osso voleranno via.", "." },
  ["3ad6a77eb5df7786"] = { "⟦Atiesh, Greatstaff of the Guardian=Atiesh, Granbastone del Guardiano⟧. Il bastone tramandato nei secoli a ciascuno dei Guardiani di Tirisfal. Il bastone corrotto da Sargeras. Il bastone dell'ultimo Guardiano. Il bastone di Medivh.", "." },
  ["3ad97ce40dec2d3b"] = { "La stalla è vuota! Dobbiamo procurare cavalcature adatte alla nostra cavalleria. Le Scuderie dei Piccatonante chiedono il tuo aiuto!", "." },
  ["3ad98b045533a7dd"] = { "Degli animali che cacciamo non si spreca nulla.", "." },
  ["3ae6d172ee070364"] = { "Non mi pagano abbastanza per questo!", "." },
  ["3ae8e3b0a2684e88"] = { "Basta... più... Feugen.", "." },
  ["3af1ae151ccf9d31"] = { "%s comincia a lanciare un controincantesimo...", "." },
})
